ShaderCache& ShaderCache::Get() {
    static ShaderCache instance;
    return instance;
}

bool ShaderCache::Initialize(const char* cachePath) {
    if (initialized_) return true;
    
    REXLOG_INFO("ShaderCache: initializing");
    
    // Try to load from embedded cache (shader_cache.cpp from XenosRecomp)
    if (LoadFromGeneratedCache()) {
        REXLOG_INFO("ShaderCache: loaded {} shaders from embedded cache", entries_.size());
    } else {
        REXLOG_WARN("ShaderCache: no embedded cache, will use runtime translation (slower, may stutter)");
    }
    
    // Try to load from disk cache if path provided
    if (cachePath) {
        LoadFromDisk(cachePath);
    }
    
    stats_.totalShaders = entries_.size();
    stats_.memoryUsage = entries_.size() * sizeof(ShaderCacheEntry); // Simplified
    
    REXLOG_INFO("ShaderCache: initialized with {} shaders, complete={}", 
                entries_.size(), IsComplete() ? "YES (6404)" : "NO");
    
    if (!IsComplete()) {
        REXLOG_WARN("ShaderCache: incomplete, expected 6404 shaders for Sonic Generations");
        REXLOG_WARN("  Generate cache via XenosRecomp workflow:");
        REXLOG_WARN("  https://github.com/Player124413/XenosRecomp/actions/workflows/recompile-shaders.yml");
        REXLOG_WARN("  Artifact 10770056313 contains cache for Generations");
    }
    
    initialized_ = true;
    return true;
}

void ShaderCache::Shutdown() {
    if (!initialized_) return;
    
    entries_.clear();
    stats_ = {};
    initialized_ = false;
    
    REXLOG_INFO("ShaderCache: shutdown");
}

const ShaderCacheEntry* ShaderCache::Find(uint64_t hash) const {
    auto it = entries_.find(hash);
    if (it != entries_.end()) {
        // Need to track stats, but const method - use mutable or atomic
        // For simplicity, not tracking here, tracking in caller
        return &it->second;
    }
    return nullptr;
}

bool ShaderCache::LoadFromGeneratedCache() {
    size_t count = 0;
    const ShaderCacheEntry* embedded = embedded_cache::GetEmbeddedCache(&count);
    
    if (!embedded || count == 0) {
        REXLOG_INFO("ShaderCache: no embedded cache found (need shader_cache.cpp from XenosRecomp)");
        return false;
    }
    
    for (size_t i = 0; i < count; ++i) {
        entries_[embedded[i].hash] = embedded[i];
    }
    
    return true;
}

bool ShaderCache::LoadFromDisk(const char* path) {
    if (!path) return false;
    
    std::ifstream file(path, std::ios::binary);
    if (!file) {
        REXLOG_WARN("ShaderCache: failed to open disk cache at {}", path);
        return false;
    }
    
    // Simple format: count + entries
    // Real implementation would be more robust
    uint64_t count = 0;
    file.read(reinterpret_cast<char*>(&count), sizeof(count));
    
    for (uint64_t i = 0; i < count; ++i) {
        ShaderCacheEntry entry;
        file.read(reinterpret_cast<char*>(&entry.hash), sizeof(entry.hash));
        // ... read rest
        // Simplified
    }
    
    REXLOG_INFO("ShaderCache: loaded {} shaders from disk cache {}", count, path);
    return true;
}

bool ShaderCache::SaveToDisk(const char* path) const {
    if (!path) return false;
    
    std::ofstream file(path, std::ios::binary);
    if (!file) {
        REXLOG_WARN("ShaderCache: failed to create disk cache at {}", path);
        return false;
    }
    
    uint64_t count = entries_.size();
    file.write(reinterpret_cast<const char*>(&count), sizeof(count));
    
    for (auto& pair : entries_) {
        // Write entry
        file.write(reinterpret_cast<const char*>(&pair.second.hash), sizeof(pair.second.hash));
        // ... simplified
    }
    
    REXLOG_INFO("ShaderCache: saved {} shaders to disk cache {}", count, path);
    return true;
}

void ShaderCache::DumpInfo() const {
    REXLOG_INFO("ShaderCache Info:");
    REXLOG_INFO("  Total shaders: {}", entries_.size());
    REXLOG_INFO("  Complete (6404): {}", IsComplete() ? "YES" : "NO");
    REXLOG_INFO("  Memory usage: {} bytes", stats_.memoryUsage);
    REXLOG_INFO("  Hits: {}, Misses: {}", stats_.cacheHits, stats_.cacheMisses);
    
    // Count by stage
    size_t vsCount = 0, psCount = 0;
    for (auto& pair : entries_) {
        if (pair.second.stage == 0) vsCount++;
        else psCount++;
    }
    REXLOG_INFO("  Vertex shaders: {}, Pixel shaders: {}", vsCount, psCount);
}

